"use client";

import { useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { Transition } from "motion/react";
import { Check, ChevronDown, Copy } from "lucide-react";
import { motionTokens } from "@/lib/motion-tokens";
import { writeClipboard } from "@/lib/use-copy-feedback";
import styles from "./tool-result.module.css";

export type ToolResultStatus = "running" | "success" | "error";

/**
 * The record of one tool call in an agent transcript. Folded, it is a single line: status, tool name, a short summary and how long
 * the call took (counting live while it runs). Open, it shows the input and the output formatted as code, each with a copy button.
 */
export interface ToolResultProps {
  /** Name of the tool that was called. */
  tool: string;
  /** Where the call stands. */
  status?: ToolResultStatus;
  /** Short text after the name, usually the main argument. */
  summary?: string;
  /** How long the call took, in milliseconds. While `status` is "running" and this is not set, a live timer counts from mount. */
  durationMs?: number;
  /** What the tool was called with. Objects are printed as highlighted JSON; strings are shown as they are. */
  input?: unknown;
  /** What the tool returned. Same formatting as `input`. */
  output?: unknown;
  /** Error message, shown in place of the output when `status` is "error". */
  error?: string;
  /** Controlled open state. */
  open?: boolean;
  /** Whether the record starts open when uncontrolled. */
  defaultOpen?: boolean;
  /** Called when the header is pressed. */
  onOpenChange?: (open: boolean) => void;
  /** Extra class for the root element. */
  className?: string;
}

const statusText: Record<ToolResultStatus, string> = { running: "Running", success: "Succeeded", error: "Failed" };
const standard = [...motionTokens.ease.standard] as [number, number, number, number];
const enterEase = [...motionTokens.ease.enter] as [number, number, number, number];
const fade: Transition = { duration: motionTokens.duration.fast, ease: standard };

export function formatDuration(ms: number) {
  if (ms < 1000) return `${Math.max(0, Math.round(ms))} ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)} s`;
  return `${Math.floor(ms / 60_000)} m ${Math.round((ms % 60_000) / 1000)} s`;
}

const tokenPattern = /("(?:\\.|[^"\\])*")(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/g;

/** Prints a value as code. Objects become indented JSON with keys, strings, numbers and literals in their own tones. */
function highlight(value: unknown): { text: string; nodes: ReactNode } {
  if (typeof value === "string") return { text: value, nodes: value };
  let text: string;
  try { text = JSON.stringify(value, null, 2) ?? String(value); } catch { text = String(value); }
  const nodes: ReactNode[] = [];
  let last = 0;
  for (const match of text.matchAll(tokenPattern)) {
    const at = match.index;
    if (at > last) nodes.push(text.slice(last, at));
    if (match[1] !== undefined && match[2] !== undefined) nodes.push(<span key={at} className={styles.key}>{match[1]}</span>, match[2]);
    else if (match[1] !== undefined) nodes.push(<span key={at} className={styles.string}>{match[1]}</span>);
    else if (match[3] !== undefined) nodes.push(<span key={at} className={styles.literal}>{match[0]}</span>);
    else nodes.push(<span key={at} className={styles.number}>{match[0]}</span>);
    last = at + match[0].length;
  }
  if (last < text.length) nodes.push(text.slice(last));
  return { text, nodes };
}

function useContentHeight() {
  const ref = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number | null>(null);
  useLayoutEffect(() => {
    const node = ref.current;
    if (!node) return;
    setHeight(node.offsetHeight);
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => setHeight(node.offsetHeight));
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  return [ref, height] as const;
}

/** Counts up while a call runs. Ticks ten times a second, or once a second under reduced motion. */
function useElapsed(active: boolean, reduce: boolean) {
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    if (!active) return;
    const started = performance.now();
    setElapsed(0);
    const timer = window.setInterval(() => setElapsed(performance.now() - started), reduce ? 1000 : 100);
    return () => window.clearInterval(timer);
  }, [active, reduce]);
  return elapsed;
}

function Section({ label, tone, value, pending, reduce, index }: { label: string; tone?: "error"; value: unknown; pending?: boolean; reduce: boolean; index: number }) {
  const code = useMemo(() => highlight(value), [value]);
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);
  async function copy() {
    try { await writeClipboard(code.text); } catch { return; }
    setCopied(true);
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => setCopied(false), 1900);
  }
  return (
    <motion.div className={styles.section} data-tone={tone} initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: motionTokens.duration.standard, ease: enterEase, delay: 0.05 + index * motionTokens.stagger.line }}>
      <div className={styles.sectionHead}>
        <span className={styles.sectionLabel}>{label}</span>
        {pending ? null : (
          <button type="button" className={styles.copy} data-done={copied || undefined} aria-label={copied ? `${label} copied` : `Copy ${label.toLowerCase()}`} onClick={copy}>
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span key={copied ? "done" : "copy"} className={styles.copyGlyph} initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.5 }} transition={reduce ? fade : { ...motionTokens.spring.snappy, opacity: fade }}>{copied ? <Check width={13} height={13} strokeWidth={2.4} aria-hidden="true" /> : <Copy width={13} height={13} strokeWidth={1.9} aria-hidden="true" />}</motion.span>
            </AnimatePresence>
          </button>
        )}
      </div>
      {pending
        ? <div className={styles.waiting} role="status" aria-label="Waiting for the result"><span /><span /><span /></div>
        : <pre className={styles.code} tabIndex={0}><code>{code.nodes}</code></pre>}
    </motion.div>
  );
}

export function ToolResult({ tool, status = "success", summary, durationMs, input, output, error, open, defaultOpen = false, onOpenChange, className }: ToolResultProps) {
  const reduce = !!useReducedMotion();
  const bodyId = useId();
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const isOpen = open ?? ownOpen;
  const [contentRef, height] = useContentHeight();
  const running = status === "running";
  const elapsed = useElapsed(running && durationMs === undefined, reduce);
  const duration = durationMs ?? (running ? elapsed : undefined);
  const hasInput = input !== undefined;
  const failed = status === "error";
  const result = failed ? error ?? output : output;

  function toggle() {
    if (open === undefined) setOwnOpen(!isOpen);
    onOpenChange?.(!isOpen);
  }

  const pop = reduce
    ? { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0 }, transition: fade }
    : { initial: { opacity: 0, scale: 0.4 }, animate: { opacity: 1, scale: 1 }, exit: { opacity: 0, scale: 0.4, transition: fade }, transition: { type: "spring" as const, visualDuration: 0.3, bounce: 0.3, opacity: fade } };
  const stroke = reduce ? { initial: false as const } : { initial: { pathLength: 0 }, animate: { pathLength: 1 }, transition: { duration: 0.26, ease: standard, delay: 0.1 } };

  return (
    <div className={[styles.root, className].filter(Boolean).join(" ")} data-status={status} data-open={isOpen || undefined}>
      <button type="button" className={styles.header} aria-expanded={isOpen} aria-controls={bodyId} onClick={toggle}>
        <span className={styles.state} aria-hidden="true">
          <AnimatePresence mode="popLayout" initial={false}>
            {running
              ? <motion.span key="running" className={styles.spinner} {...pop} />
              : <motion.span key={status} className={styles.badge} {...pop}>
                  <svg viewBox="0 0 16 16">
                    {failed
                      ? <><motion.path d="M5 5 11 11" {...stroke} /><motion.path d="M11 5 5 11" {...stroke} /></>
                      : <motion.path d="M4 8.4 6.9 11.1 12 5.2" {...stroke} />}
                  </svg>
                </motion.span>}
          </AnimatePresence>
        </span>
        <span className={styles.srOnly}>{statusText[status]}: </span>
        <code className={styles.tool}>{tool}</code>
        <span className={styles.summary}>{summary}</span>
        {duration !== undefined ? <span className={styles.duration}><span className={styles.srOnly}>{running ? "running for " : "took "}</span>{formatDuration(duration)}</span> : null}
        <ChevronDown className={styles.chevron} width={15} height={15} strokeWidth={2} aria-hidden="true" />
      </button>
      {/* The body stays mounted so its height is always known: opening, closing and a result arriving all spring to the measured size. */}
      <motion.div id={bodyId} className={styles.region} inert={!isOpen} initial={false} animate={{ height: isOpen ? height ?? "auto" : 0, opacity: isOpen ? 1 : 0 }} transition={reduce ? { duration: 0 } : { height: motionTokens.spring.smooth, opacity: { duration: motionTokens.duration.standard, ease: standard } }}>
        <div ref={contentRef} className={styles.body}>
          {/* Keyed by the open state so the sections step in again each time the record opens. */}
          <div key={isOpen ? "open" : "closed"} className={styles.sections}>
            {hasInput ? <Section label="Input" value={input} reduce={reduce || !isOpen} index={0} /> : null}
            <Section key={running ? "waiting" : status} label={failed ? "Error" : "Output"} tone={failed ? "error" : undefined} value={result ?? ""} pending={running} reduce={reduce || !isOpen} index={hasInput ? 1 : 0} />
          </div>
        </div>
      </motion.div>
    </div>
  );
}

export default ToolResult;

.root { --mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace; --tool-tone: var(--success); width: 100%; min-width: 0; box-sizing: border-box; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); text-align: left; transition: border-color var(--duration-standard) var(--ease-standard), box-shadow var(--duration-standard) var(--ease-standard); }
.root[data-status="error"] { --tool-tone: var(--danger); }
.root[data-open] { border-color: var(--border-strong); box-shadow: var(--shadow-resting); }

.header { display: flex; width: 100%; min-height: 42px; box-sizing: border-box; align-items: center; gap: var(--space-2); padding: 0 var(--space-3); border: 0; background: transparent; color: inherit; font: inherit; text-align: left; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-fast) var(--ease-standard); }
.header:focus-visible { --focus-outline-offset: -3px; border-radius: var(--radius-control); }
@media (hover: hover) and (pointer: fine) { .header:hover { background: color-mix(in oklab, var(--surface-muted) 55%, transparent); } }
.state { position: relative; display: grid; width: 20px; height: 20px; flex: none; place-items: center; }
.spinner, .badge { display: grid; grid-area: 1 / 1; box-sizing: border-box; place-items: center; border-radius: var(--radius-pill); }
.spinner { width: 16px; height: 16px; border: 2px solid var(--accent-subtle); border-top-color: var(--accent-strong); animation: tool-spin .8s linear infinite; }
.badge { width: 20px; height: 20px; background: color-mix(in oklab, var(--tool-tone) 16%, transparent); color: var(--tool-tone); }
.badge svg { display: block; width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.tool { flex: none; max-width: 55%; overflow: hidden; font-family: var(--mono); font-size: var(--text-sm); font-weight: 500; letter-spacing: 0; text-overflow: ellipsis; white-space: nowrap; }
.summary { min-width: 0; flex: 1; overflow: hidden; color: var(--text-muted); font-size: var(--text-sm); text-overflow: ellipsis; white-space: nowrap; }
.duration { flex: none; color: var(--text-secondary); font-size: var(--text-xs); font-variant-numeric: tabular-nums; white-space: nowrap; }
.root[data-status="running"] .duration { color: var(--accent-strong); }
.chevron { flex: none; color: var(--text-muted); transition: rotate var(--duration-spring) var(--ease-spring); }
.header[aria-expanded="false"] .chevron { rotate: -90deg; }

.region { overflow: hidden; }
.sections { display: grid; gap: var(--space-3); padding: var(--space-1) var(--space-3) var(--space-3); }
.section { display: grid; min-width: 0; gap: 6px; }
.sectionHead { display: flex; min-height: 24px; align-items: center; justify-content: space-between; gap: var(--space-2); }
.sectionLabel { color: var(--text-muted); font-size: var(--text-xs); font-weight: 600; letter-spacing: .04em; text-transform: uppercase; }
.section[data-tone="error"] .sectionLabel { color: var(--danger); }
.copy { position: relative; display: grid; width: 24px; height: 24px; flex: none; padding: 0; place-items: center; border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--text-muted); cursor: pointer; -webkit-tap-highlight-color: transparent; transition: scale var(--duration-spring) var(--ease-spring), background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
.copy:active { scale: .88; transition-duration: var(--duration-instant); }
.copy[data-done] { color: var(--success); }
.copyGlyph { display: grid; grid-area: 1 / 1; place-items: center; }
@media (hover: hover) and (pointer: fine) { .copy:hover { background: var(--surface-muted); color: var(--foreground); } .copy[data-done]:hover { color: var(--success); } }
.code { max-height: 15rem; margin: 0; padding: var(--space-3); overflow: auto; border-radius: 12px; background: var(--surface-muted); color: var(--foreground); font-family: var(--mono); font-size: var(--text-xs); line-height: 1.65; letter-spacing: 0; white-space: pre-wrap; overflow-wrap: anywhere; tab-size: 2; scrollbar-width: thin; }
.code:focus-visible { --focus-outline-offset: -2px; }
.code code { font: inherit; }
.section[data-tone="error"] .code { background: color-mix(in oklab, var(--danger) 9%, var(--surface)); color: var(--danger); }
/* Code tones come from the categorical palette, which is tuned for text in both themes. */
.key { color: var(--tone-sky); }
.string { color: var(--tone-green); }
.number { color: var(--tone-amber); }
.literal { color: var(--tone-violet); }

/* Placeholder lines while the call runs. Functional gradient: a skeleton shimmer. */
.waiting { display: grid; gap: 8px; padding: var(--space-3); border-radius: 12px; background: var(--surface-muted); }
.waiting span { display: block; height: 9px; border-radius: var(--radius-pill); background: linear-gradient(100deg, var(--border) 30%, var(--border-strong) 50%, var(--border) 70%) 0 0 / 300% 100%; animation: tool-shimmer 1.5s linear infinite; }
.waiting span:nth-child(1) { width: 72%; }
.waiting span:nth-child(2) { width: 54%; animation-delay: .12s; }
.waiting span:nth-child(3) { width: 38%; animation-delay: .24s; }
.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@keyframes tool-spin { to { rotate: 360deg; } }
@keyframes tool-shimmer { from { background-position: 100% 0; } to { background-position: -50% 0; } }
@media (prefers-reduced-motion: reduce) {
  .root, .header, .chevron, .copy { transition: none; }
  .copy:active { scale: none; }
  .spinner, .waiting span { animation: none; }
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export type CopyFeedbackState = "idle" | "copied" | "error";

/**
 * Writes text to the clipboard. Uses the async Clipboard API and falls back to a hidden textarea with
 * document.execCommand("copy") when the API is missing or refused (sandboxed or cross-origin iframes, Safari
 * inside embedded previews, insecure contexts). Must be called from a user gesture. Rejects only when both fail.
 */
export async function writeClipboard(text: string): Promise<void> {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return;
    }
  } catch {
    // Fall through to the legacy path below.
  }
  const active = document.activeElement as HTMLElement | null;
  const selection = document.getSelection();
  const ranges = selection ? Array.from({ length: selection.rangeCount }, (_, index) => selection.getRangeAt(index)) : [];
  const area = document.createElement("textarea");
  area.value = text;
  area.setAttribute("readonly", "");
  area.style.cssText = "position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;pointer-events:none;";
  document.body.appendChild(area);
  area.select();
  area.setSelectionRange(0, text.length);
  let ok = false;
  try { ok = document.execCommand("copy"); } catch { ok = false; }
  area.remove();
  if (selection) { selection.removeAllRanges(); ranges.forEach(range => selection.addRange(range)); }
  active?.focus?.({ preventScroll: true });
  if (!ok) throw new Error("Copy failed");
}

/** Shared clipboard state for actions that render their own button or menu. */
export function useCopyFeedback(duration = 1900) {
  const [state, setState] = useState<CopyFeedbackState>("idle");
  const [activeKey, setActiveKey] = useState<string | null>(null);
  const timeout = useRef<ReturnType<typeof setTimeout> | null>(null);

  const reset = useCallback(() => {
    if (timeout.current) clearTimeout(timeout.current);
    timeout.current = null;
    setState("idle");
    setActiveKey(null);
  }, []);

  useEffect(() => () => {
    if (timeout.current) clearTimeout(timeout.current);
  }, []);

  const copy = useCallback(async (value: string, key = "default") => {
    if (timeout.current) clearTimeout(timeout.current);
    setActiveKey(key);
    try {
      await writeClipboard(value);
      setState("copied");
      timeout.current = setTimeout(reset, duration);
      return true;
    } catch {
      setState("error");
      timeout.current = setTimeout(reset, duration);
      return false;
    }
  }, [duration, reset]);

  return { state, activeKey, copy, reset };
}
